export default function ContactForm() {
  async function submitContactMessage(formData: FormData) {
    'use server';

    const name = formData.get('name') as string;
    const email = formData.get('email') as string;
    const message = formData.get('message') as string;

    // JavaScript validation to check that all fields are provided
    if (!name || !name.trim() || !email || !email.trim() || !message || !message.trim()) {
      console.error('Validation Error: Name, email, and message are required.');
      return;
    }

    console.log('Contact message received:', { name, email, message });
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContactMessage}>
        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="name" style={{ display: 'block' }}>Name</label>
          <input type="text" id="name" name="name" required />
        </div>

        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="email" style={{ display: 'block' }}>Email</label>
          <input type="email" id="email" name="email" required />
        </div>

        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="message" style={{ display: 'block' }}>Message</label>
          <textarea id="message" name="message" required rows={4}></textarea>
        </div>

        <button type="submit">Submit</button>
      </form>
    </div>
  );
}
